// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        address ceoBefore = c.ceoAddress();

        bool ok;
        vm.prank(actor);
        try c.DrugDealer() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for every admissible actor, a successful DrugDealer call
        // by actor leaves ceoAddress == actor (the caller is bound as CEO);
        // a reverting call leaves ceoAddress untouched.
        assertTrue(
            ok ? c.ceoAddress() == actor : c.ceoAddress() == ceoBefore,
            "DrugDealer must bind the caller as CEO on success"
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        address before = c.ceoAddress();
        vm.prank(actor);
        try c.DrugDealer() {
            // Rule: after a successful DrugDealer call by any caller, the contract's
            // public getter must report that caller as the CEO.
            assertTrue(c.ceoAddress() == actor && c.ceoAddress() == before || c.ceoAddress() == actor, "ceoAddress must track the last successful DrugDealer caller");
        } catch {
            // Rule: if the call reverts, the stored CEO must be untouched.
            assertTrue(c.ceoAddress() == before, "failed DrugDealer must not change ceoAddress");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address a, address b) public {
        vm.assume(a != b);
        vm.assume(a != address(0) && b != address(0));
        vm.assume(uint160(a) > 10 && uint160(b) > 10);

        address before = c.ceoAddress();

        // First fuzzed actor attempts to claim the CEO role.
        vm.prank(a);
        bool ok1;
        try c.DrugDealer() { ok1 = true; } catch { ok1 = false; }

        // Second fuzzed actor attempts to claim the CEO role.
        vm.prank(b);
        bool ok2;
        try c.DrugDealer() { ok2 = true; } catch { ok2 = false; }

        // General rule: the public CEO pointer must always equal the address of
        // the most recent SUCCESSFUL DrugDealer caller, or remain the previous
        // value if that call reverted. The buggy version never reassigns
        // ceoAddress, so for a successful call by an address that is not the
        // pre-call CEO, the getter reports a stale value and the rule breaks.
        assertTrue(ok1 ? (c.ceoAddress() == a) : (ok2 ? (c.ceoAddress() == b) : (c.ceoAddress() == before)));
    }
}

